CREATE OR REPLACE FUNCTION promotions.touch_updated_at()
RETURNS trigger AS $$
BEGIN
NEW.updated_at = now();
RETURN NEW;
END;
$$ LANGUAGE plpgsql;

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_count
CHECK (batch_count >= 0 AND batch_count <= 1000000);

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_code_length
CHECK (code_length >= 8 AND code_length <= 12);

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_status
CHECK (status IN ('PENDING','RUNNING','COMPLETED','FAILED'));

DROP TRIGGER IF EXISTS promo_batch_touch_updated_at ON promotions.promo_batch;
CREATE TRIGGER promo_batch_touch_updated_at
BEFORE UPDATE ON promotions.promo_batch
FOR EACH ROW
EXECUTE FUNCTION promotions.touch_updated_at();

CREATE INDEX IF NOT EXISTS idx_promo_batch_status
ON promotions.promo_batch(status);

CREATE INDEX IF NOT EXISTS idx_promo_batch_opera_promo
ON promotions.promo_batch(opera_promo);

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_status
CHECK (status IN ('PENDING','RUNNING','COMPLETED','FAILED','EXPIRED'));

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_prefix_length
CHECK (
prefix IS NULL
OR char_length(prefix) BETWEEN 1 AND 25
);

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_prefix_length
CHECK (
prefix IS NULL
OR char_length(prefix) BETWEEN 1 AND 20
);

ALTER TABLE promotions.promo_batch
ADD CONSTRAINT chk_promo_batch_code_length
CHECK (
code_length >= 8
AND code_length <= 40
);
